window.SantaLocaleSV.missions.push(...[{"title":"❄️ Snöglobskatastrofen","skill":"Att förvandla en idé till något interaktivt.","message":"NÖDLÄGE!\n\nNissen Kevin stoppade min favoritsnöglob i diskmaskinen.\n\nSnön smälte. Julgranarna välte. Och jag kanske grät lite.\n\nJag behöver en ny magisk snöglob genast!","intro":"Skapa en interaktiv julsnöglob.","requirements":["Visa ett julmotiv i en glaskula.","Låt snön falla hela tiden.","Låt användaren skaka globen med musen eller fingret.","Lägg in en julöverraskning när man klickar eller trycker någonstans.","Se till att den fungerar på dator och mobil."],"bonus":"Låt snön reagera när någon skakar mobilen på riktigt, om enheten stöder det.","help":["Föreställ dig en glaskula med ett litet julhus, ett träd och fallande snö. När man skakar den virvlar snön runt.","Börja med att utforma globen och landskapet. Lägg till snöfallet, sedan mus- och pekstyrning och till sist en hemlig överraskning, till exempel ett lysande fönster eller tomten.","Hjälp mig att skapa min första interaktiva julsnöglob. Jag är nybörjare. Den ska ha en söt julscen, animerad snö, skakning med mus och pekskärm samt en hemlig överraskning. Ställ en enkel fråga i taget så jag kan bestämma utseendet. Skriv sedan en detaljerad byggprompt för en enda fristående HTML-fil med all CSS och JavaScript inbyggd. Förklara hur jag skapar filen med gratis ChatGPT eller Work. Håll projektet lagom enkelt."]},{"title":"🎮 Fånga julklapparna!","skill":"Att förklara spelregler och beteenden tydligt.","message":"Transportbandet med julklappar har blivit helt galet!\n\nPaketen faller från taket och nissen Kevin gömmer sig under ett bord.\n\nVi behöver någon modig som kan fånga dem!","intro":"Skapa ett enkelt julspel.","requirements":["Flytta en nisse åt vänster och höger längst ned på skärmen.","Låt julklappar falla uppifrån.","Ge 10 poäng för varje fångat paket.","Undvik fallande kolbitar.","Spelet slutar efter tre misstag.","Visa poäng och en knapp för att börja om.","Stöd både tangentbord och pekskärm."],"extra":"Bara en skärm, inga komplicerade nivåer.","bonus":"Låt paketen falla snabbare när poängen ökar.","help":["Föreställ dig en nisse som står längst ned och försöker fånga paket i en korg, men undvika kol.","Börja med en nisse som går att flytta. Lägg till fallande julklappar och kol, sedan poäng, tre liv och kollisionsregler. Avsluta med omstart och touchkontroller.","Hjälp mig skapa ett enkelt julspel på en skärm. En nisse ska gå åt höger och vänster, fånga fallande julklappar och undvika kol. Varje paket ger 10 poäng och spelet tar slut efter tre misstag. Lägg till tangentbords- och pekstyrning, poängräknare och omstart. Jag är ny på att skapa med AI. Ställ en fråga i taget om designen. Skriv sedan en detaljerad prompt för en komplett offline HTML-fil med inbyggd CSS och JavaScript. Håll spelet enkelt."]},{"title":"🎁 Nordpolens designavdelning","skill":"Att bygga ett verktyg som andra kan använda.","message":"KATASTROF!\n\nVi har fått 400 klagomål på fult presentpapper.\n\nNissarna påstår att brunt papper är 'minimalistiskt'.\n\nJag tycker att alla ska få sparken. Tomtemor tycker att jag ska lugna mig.\n\nBygg en julklappsdesigner åt oss.","intro":"Skapa en interaktiv julklappsdesigner.","requirements":["Visa ett inslaget paket.","Låt användaren välja färger och mönster på presentpappret.","Erbjud olika band och rosetter.","Lägg till minst två valfria dekorationer.","Skapa en 'Överraska mig'-knapp som ger en slumpmässig design."],"bonus":"Låt användaren ladda ned en bild av sin julklapp.","help":["Föreställ dig ett paket som ändrar utseende när man väljer papper, band och dekorationer.","Bygg först en förhandsvisning av paketet. Lägg till färger och mönster, sedan band, rosetter och pynt. Avsluta med slumpknappen.","Hjälp mig planera en söt interaktiv julklappsdesigner. Användare ska kunna välja färger, mönster, band, rosetter och pynt. En 'Överraska mig'-knapp behövs. Ställ en enkel fråga i taget om utseende och funktion. Skriv sedan en detaljerad prompt för en enda fristående HTML-fil med alla bilder, CSS och JavaScript inbyggda. Den ska fungera på dator och mobil."]},{"title":"🕵️ Vem stal tomtens kakor?","skill":"Att planera interaktioner och koppla ihop ledtrådar.","message":"NÅGON HAR STULIT MINA KAKOR!\n\nTre misstänkta nissar syntes nära köket.\n\nEn har smulor på mössan. En annan luktar kanel.\n\nKevin säger att han sov. Kevin är alltid misstänkt.","intro":"Skapa ett enkelt interaktivt julmysterium.","requirements":["Presentera tre roliga misstänkta nissar.","Låt spelaren förhöra dem med knappar.","Varje misstänkt avslöjar en ledtråd.","Låt spelaren anklaga en av dem.","Visa om anklagelsen är rätt och varför.","Ha en 'Spela igen'-knapp."],"extra":"Mysteriet ska vara litet och lätt att förstå.","bonus":"Lägg till en dold ledtråd.","help":["Hitta på tre misstänkta med varsin rolig personlighet och ledtråd. Bestäm vem som faktiskt tog kakorna.","Bestäm först vem som är skyldig. Skriv ett kort påstående och en ledtråd för varje nisse. Bygg ett enkelt val av misstänkt, förhör och resultat.","Hjälp mig designa ett enkelt juldeckarspel: 'Vem stal tomtens kakor?' Det ska finnas tre misstänkta nissar som avslöjar en ledtråd var vid förhör. Spelaren pekar ut den skyldige och får en förklaring. Hjälp mig hitta på ett mysterium som går att lösa logiskt. Ställ en fråga i taget. Skriv sedan en detaljerad byggprompt för ett fristående HTML-spel med CSS och JavaScript som fungerar på mobil och dator."]},{"title":"🎁 Tomtens omöjliga julklappsguide","skill":"Att lösa problem med frågor och regler.","message":"Jag måste erkänna något hemskt.\n\nFörra året gav jag farmor en skateboard.\n\nÅret innan gav jag en guldfisk en cykel.\n\nJag tror att jag behöver professionell hjälp.","intro":"Bygg ett verktyg som föreslår julklappar.","requirements":["Ställ minst fyra frågor om mottagaren.","Använd svaren till att rekommendera presenter.","Visa minst två förslag.","Förklara varför varje förslag passar.","Låt användaren börja om.","Den färdiga HTML-filen ska fungera utan någon uppkopplad AI-tjänst."],"bonus":"Lägg till ett läge för 'Hemskt dåliga presentidéer'.","help":["Tänk på vad du frågar när du ska köpa en present. Intressen, ålder, hobbyer och budget är bra början.","Skapa fyra frågor med svarsalternativ. Hitta på presentförslag och regler som matchar svaren med presenter. Visa de bästa förslagen och förklara varför.","Hjälp mig bygga en offline julklappsguide. Den ska ställa fyra frågor om en person, rekommendera minst två presenter och förklara varje förslag. Använd förutbestämda presenter och enkla regler, inte ett AI-API. Ställ en fråga i taget när vi planerar frågorna och resultaten. Skriv sedan en detaljerad prompt för en fin fristående HTML-fil som fungerar på mobil och dator."]},{"title":"🎵 Nisse-DJ-katastrofen","skill":"Att skapa med ljud och timing.","message":"Vår jul-DJ har spelat samma låt 93 gånger.\n\nRenarna hotar att flytta.\n\nBygg en musikmaskin innan julfesten blir en katastrof.","intro":"Skapa en julmusikmaskin.","requirements":["Ha minst fem knappar med olika ljud eller toner.","Låt användaren spela ljuden i valfri ordning.","Lägg till en inspelningsknapp.","Lägg till en stoppknapp.","Låt användaren spela upp den inspelade sekvensen.","Skapa ljuden i webbläsaren utan externa ljudfiler."],"bonus":"Lägg till kontroll för uppspelningshastighet.","help":["Föreställ dig ett litet piano av julklockor. Varje knapp spelar en ton och man kan spela in sin melodi.","Börja med fem fungerande tonknappar. Spara sedan vilka knappar som trycks ned och när. Lägg till stopp och uppspelning.","Hjälp mig skapa en julmusikmaskin med fem knappar som spelar toner. Användaren ska kunna spela, spela in en kort melodi och lyssna på den igen. Använd ljud som skapas i webbläsaren i stället för ljudfiler. Ställ en enkel designfråga i taget. Skriv sedan en komplett byggprompt för en fristående HTML-fil med CSS, JavaScript och Web Audio API inbyggt. Den ska fungera på dator och mobil."]}]);

window.SantaLocaleSV.missions.push(...[{"title":"🧝 Skapa din egen julnisse","skill":"Att bygga ett verktyg med egna val.","message":"Vår personalavdelning har tappat bort alla foton på nissarna.\n\nKevin hade tydligen lagt dem i mikrovågsugnen.\n\nVi behöver en maskin som kan skapa helt nya nissefigurer!","intro":"Skapa en julnisse-byggare.","requirements":["Visa en söt tecknad nisse.","Låt användaren byta mössa.","Låt användaren byta kläder och tillbehör.","Låt användaren välja nissens namn.","Lägg till en knapp för en slumpmässig nisse."],"bonus":"Gör ett figurkort med namn, utseende och personlighet.","help":["Föreställ dig att klä på en tecknad nisse. Man ska kunna göra många olika kombinationer av mössor och kläder.","Börja med en bild av nissen. Lägg till knappar för mössa, kläder och tillbehör, ett namnfält och en slumpknapp.","Hjälp mig skapa en söt julnisse-byggare. Användaren ska kunna välja mössa, kläder, tillbehör och namn och få en slumpmässig nisse. Bilderna ska skapas med inbyggd SVG eller CSS så HTML-filen fungerar offline. Ställ en fråga i taget om utseendet. Skriv sedan en detaljerad byggprompt för en enda komplett fristående HTML-fil med all kod och alla bilder inbyggda."]},{"title":"🎬 Sälj din uppfinning till tomten","skill":"Att presentera idéer med bilder.","message":"NYHETER!\n\nNordpolen håller sin årliga uppfinnartävling.\n\nVinnaren får obegränsat med kakor under ett helt år.\n\nKevin har anmält en brödrost som brer sig själv. Kom på något bättre.","intro":"Skapa en animerad HTML-presentation om en juluppfinning.","requirements":["Hitta på en användbar eller tokig julprodukt.","Gör fem bilder eller scener.","Förklara problemet som produkten löser.","Presentera uppfinningen och visa hur den fungerar.","Lägg till animationer eller övergångar.","Avsluta med ett övertygande säljtal.","Resultatet ska vara HTML, inte PowerPoint."],"bonus":"Lägg till en animerad demonstration av produkten.","help":["Hitta på ett tokigt problem på Nordpolen och en maskin som löser det. Föreställ dig att du vill övertyga tomten att köpa den.","Använd fem delar: Problemet, Din stora idé, Visa produkten, Så fungerar den och Varför tomten behöver den.","Hjälp mig hitta på en rolig julprodukt och skapa en interaktiv presentation med fem bilder som säljer den till tomten. Den ska förklara problem, idé, produkt, demonstration och säljtal. Ställ en fråga i taget så att jag tar de kreativa besluten. Skriv sedan en detaljerad byggprompt för en snygg fristående HTML-presentation med animationer, inbyggd grafik, CSS och JavaScript."]},{"title":"🛠️ Operation: Fixa något irriterande","skill":"Att hitta ett verkligt problem och lösa det.","message":"Jag har upptäckt något chockerande.\n\nTydligen har människor också problem.\n\nAllt kretsar inte kring renar och kakor.\n\nUndersök saken!","intro":"Skapa ett litet verktyg som underlättar vardagen.","requirements":["Välj till exempel läxplanering, packlista, beslutshjälp eller ett eget problem.","Beskriv ett tydligt problem.","Bygg ett interaktivt verktyg som hjälper till.","Gör det lätt för någon annan att förstå.","Testa med ett riktigt exempel.","Förbättra minst en sak efter testet."],"bonus":"Låt någon annan prova verktyget och föreslå en förbättring.","help":["Om du inte har en idé, gör en packlista för en helgresa.","Skapa en checklista där man kan lägga till saker, bocka av, ta bort och se hur många saker som återstår.","Hjälp mig skapa ett litet användbart verktyg i vardagen. Om jag saknar egen idé, hjälp mig göra en packlista för en helgresa. Man ska kunna lägga till saker, bocka av, ta bort saker och spara framsteg lokalt. Ställ en fråga i taget om funktioner och utseende. Skriv sedan en detaljerad byggprompt för en enda fristående HTML-fil som fungerar offline på mobil och dator."]},{"title":"🔐 Fly från Nordpolen!","skill":"Att dela upp stora projekt i mindre delar.","message":"HJÄLP!\n\nKevin har låst in alla i verkstaden.\n\nKoden till nödutgången stod skriven på en kaka.\n\nNågon åt upp kakan.\n\nJag tänker inte nämna några namn. Kevin.","intro":"Skapa ett litet jul-escape room.","requirements":["Visa ett enda julverkstadsrum.","Lägg till tre klickbara föremål.","Varje föremål öppnar ett pussel.","Ha ett sifferpussel, ett färg-/mönsterpussel och en gåta.","Varje löst pussel avslöjar en siffra i en tresiffrig kod.","Låt spelaren mata in koden för att fly.","Lägg till en starta-om-knapp."],"extra":"Inga extra rum eller komplicerade äventyr.","bonus":"Lägg till en timer.","help":["Föreställ dig ett låst rum med en klocka, ett paket och en mystisk lapp. Varje sak gömmer ett pussel.","Planera alla tre pussel först. Varje pussel ger en siffra. Kombinera siffrorna till den slutliga koden.","Hjälp mig planera ett litet jul-escape room med ett verkstadsrum, tre klickbara föremål och tre enkla pussel. Jag vill ha ett sifferpussel, ett färg-/mönsterpussel och en gåta. Varje löst pussel avslöjar en siffra i en tresiffrig kod. Ställ en fråga i taget om pussel och design och se till att gåtorna går att lösa logiskt. Skriv sedan en detaljerad prompt för en fristående HTML-fil med inbyggd CSS, JavaScript, mobilstöd och omstart."]},{"title":"✨ Den stora juluppgraderingen","skill":"Att utvärdera och förbättra något du skapat.","message":"Jag har granskat dina uppfinningar.\n\nDe är fantastiska.\n\nMen jag undrar en sak.\n\nKan en av dem bli ÄNNU MER FANTASTISK?!\n\nTomtemor säger att jag ska sluta skrika.","intro":"Välj en tidigare uppfinning och förbättra den.","requirements":["Öppna ett tidigare HTML-projekt.","Hitta tre saker att förbättra.","Diskutera förbättringarna med AI.","Lägg till minst en ny funktion.","Testa den förbättrade versionen.","Spara som en NY fristående HTML-fil.","Behåll originalet."],"bonus":"Be AI granska projektet efter problem och fixa ett av dem.","help":["Välj ditt favoritprojekt. Vad skulle göra det finare, roligare eller mer användbart?","Ge AI den gamla HTML-filen. Beskriv tre förbättringar och en ny funktion. Be AI bevara allt som redan fungerar.","Jag har ett HTML-projekt som jag vill förbättra. Be mig först dela den ursprungliga HTML-filen. Hjälp mig hitta tre förbättringar genom att ställa en fråga i taget. Hjälp mig sedan välja minst en ny funktion. Skriv en detaljerad byggprompt som säger att AI ska behålla allt som fungerar, göra förbättringarna, testa efter fel och leverera en komplett NY fristående HTML-fil. Skriv inte över originalet."]},{"title":"🎄 Tomtens sista hemliga uppdrag","skill":"Att skapa och lösa problem självständigt.","message":"AGENT!\n\nDu har klarat elva hemliga uppdrag.\n\nDu har räddat min snöglob, roat nissarna, löst mysterier och förhindrat minst fyra julkatastrofer.\n\nTill och med Kevin är imponerad.\n\nJag har ett sista uppdrag.\n\nDen här gången bestämmer DU vad vi ska bygga.\n\nÖverraska mig.","intro":"Skapa ett helt eget interaktivt julprojekt.","requirements":["Välj till exempel ett magiskt julkort, ett roligt personlighetstest, en nedräkning med överraskningar eller något helt eget.","Välj din idé.","Bestäm hur det ska se ut och fungera.","Planera tillsammans med AI.","Bygg en fristående HTML-fil.","Testa och förbättra.","Visa upp det för någon i familjen."],"bonus":"Skapa något som får någon att skratta.","help":["Tänk på ditt favorituppdrag hittills. Vill du skapa något roligt, vackert, användbart eller överraskande?","Om du fastnar kan du göra ett magiskt julkort med animerade dekorationer, en personlig hälsning och en knapp som visar en överraskning.","Hjälp mig skapa ett originellt interaktivt julkort till min familj. Det ska ha en personlig hälsning, söta animerade dekorationer, en knapp med en överraskning och en magisk julkänsla. Ställ en fråga i taget så att jag får ta de kreativa besluten. Skriv sedan en detaljerad byggprompt för en fristående HTML-fil med all CSS, JavaScript och alla illustrationer inbyggda. Det ska vara möjligt för en nybörjare."]}]);

window.SantaLocaleSV.story = "TOPPHEMLIGT! Nordpolen behöver en ny uppfinnare.\n\nTomtens verkstad har stora problem.\n\nNissarna är fantastiska på att tillverka leksaker, men hopplösa på teknik.\n\nDärför har tomten i hemlighet rekryterat DIG.\n\nVarannan dag kommer ett nytt hemligt uppdrag från Nordpolen.\n\nVissa uppdrag är viktiga. Andra är knasiga. Och några beror säkert på att nissen Kevin tryckt på fel knapp.\n\nDin uppgift är att använda AI för att hitta på, bygga och fixa saker.\n\nDu behöver inte kunna skapa något innan du börjar.\n\nDet räcker med en idé, lite tålamod och din AI-assistent.\n\nLycka till, agent {childName}!\n\n— Jultomten\n\nP.S. Berätta inget för nissen Kevin. Han tror att han ansvarar för tekniken.";
window.SantaLocaleSV.rules = [["Tänk innan du bygger 🧠",["Börja i en vanlig ChatGPT-chatt.","Prata om din idé och fundera ut vad du vill skapa innan du ber AI att bygga det.","Du behöver inte kunna programmera."]],["Låt AI ställa frågor 💬",["Prova att säga:","\"Ställ en fråga i taget tills vi vet allt som behövs för att bygga min idé.\"","Du behöver inte kunna svara på allt direkt."]],["Planera först – bygg sedan! 🛠️",["När du har planerat ditt projekt, be ChatGPT skriva en detaljerad byggprompt.","Använder du ChatGPT Work? Ge Work din prompt och be om en nedladdningsbar HTML-fil.","Använder du gratis ChatGPT? Be om all HTML-kod eller, om möjligt, en nedladdningsbar HTML-fil.","Om du får kod i stället för en fil, spara hela koden som en .html-fil.","Båda sätten fungerar. Det viktiga är vad DU skapar!"]],["En magisk HTML-fil ✨",["Varje uppdrag ska resultera i EN komplett, fristående .html-fil.","All CSS och JavaScript ska finnas i samma fil.","Den ska fungera utan externa filer, bibliotek, installationer eller internet."]],["Lita inte på första försöket 🔍",["Testa det du har skapat.","Om något ser konstigt ut eller inte fungerar, beskriv problemet för AI och be om en rättning.","Gör alltid minst en förbättring."]],["DU är uppfinnaren! 🎨",["Tomten ger dig uppdraget, men DU tar de kreativa besluten.","AI får föreslå idéer, men ska inte bestämma allt åt dig."]],["Ha roligt! 🍪",["Misstag är en del av att uppfinna.","Till och med tomtens nissar råkar ibland skapa exploderande pepparkakor."]]];
